2	import { NextRequest, NextResponse } from "next/server";
3	import { getSession } from "@/lib/auth";
4	import { prisma } from "@/lib/prisma";
5	
6	export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
7	  const session = await getSession();
8	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
9	
10	  const { id: quizId } = await params;
11	  const body = await req.json();
12	  const answers = (body?.answers ?? {}) as Record<string, string>;
13	
14	  const quiz = await prisma.quiz.findUnique({
15	    where: { id: quizId },
16	    include: {
17	      questions: { orderBy: { order: "asc" } },
18	      folder: { select: { courseId: true, course: { select: { teacherId: true } } } },
19	      planLesson: { select: { id: true, planId: true } },
20	    },
21	  });
22	
23	  if (!quiz) return NextResponse.json({ error: "الاختبار غير موجود" }, { status: 404 });
24	
25	  const canAccessAsTeacher = session.role === "teacher" && (
26	    (quiz.folder?.course?.teacherId === session.id) ||
27	    (quiz.planLessonId !== null)
28	  );
29	
30	  let canAccessAsStudent = false;
31	  let planEnrollmentId: string | null = null;
32	
33	  if (quiz.folderId && quiz.folder) {
34	    const hasCourseAccess = await prisma.accessCode.findFirst({
35	      where: {
36	        courseId: quiz.folder.courseId,
37	        studentId: session.id,
38	        isActive: true,
39	      },
40	      select: { id: true },
41	    });
42	    if (hasCourseAccess) canAccessAsStudent = true;
43	  } else if (quiz.planLessonId && quiz.planLesson) {
44	    const enrollment = await prisma.planEnrollment.findFirst({
45	      where: {
46	        planId: quiz.planLesson.planId,
47	        studentId: session.id,
48	        expiresAt: { gt: new Date() },
49	      },
50	      select: { id: true },
51	    });
52	    if (enrollment) {
53	      canAccessAsStudent = true;
54	      planEnrollmentId = enrollment.id;
55	    }
56	  }
57	
58	  if (!canAccessAsTeacher && !canAccessAsStudent) {
59	    return NextResponse.json({ error: "لا يوجد صلاحية للوصول" }, { status: 403 });
60	  }
61	
62	  const totalQ = quiz.questions.length;
63	  if (!totalQ) return NextResponse.json({ error: "الاختبار بدون أسئلة" }, { status: 400 });
64	
65	  // Block retake unless teacher allowed it
66	  const existingResult = await prisma.quizResult.findUnique({
67	    where: { studentId_quizId: { studentId: session.id, quizId } },
68	  });
69	
70	  if (!existingResult || !existingResult.startedAt) {
71	    return NextResponse.json(
72	      { error: "لم يتم بدء الاختبار بشكل صحيح. يرجى بدء الاختبار من الصفحة المخصصة أولاً." },
73	      { status: 400 }
74	    );
75	  }
76	
77	  if (!existingResult.allowRetake && existingResult.completedAt && (existingResult.score > 0 || existingResult.totalQ > 0)) {
78	    // Only block if they have already submitted and completed it
79	    return NextResponse.json(
80	      { error: "لقد أجبت على هذا الاختبار بالفعل. تواصل مع المعلم للسماح بإعادة المحاولة." },
81	      { status: 409 }
82	    );
83	  }
84	
85	  const dbStartedAt = existingResult.startedAt;
86	  const limitMinutes = (quiz as any).timeLimitMinutes ?? 30;
87	  const elapsedSeconds = Math.floor((Date.now() - dbStartedAt.getTime()) / 1000);
88	  if (elapsedSeconds > limitMinutes * 60) {
89	    return NextResponse.json({ error: "انتهى وقت الاختبار" }, { status: 400 });
90	  }
91	
92	  const breakdown = quiz.questions.map((question: any) => {
93	    const yourAnswer = answers[question.id] ?? null;
94	    const isCorrect = yourAnswer === question.correctAnswer;
95	    return {
96	      questionId: question.id,
97	      question: question.question,
98	      optionA: question.optionA,
99	      optionB: question.optionB,
100	      optionC: question.optionC,
101	      optionD: question.optionD,
102	      yourAnswer,
103	      correctAnswer: question.correctAnswer,
104	      isCorrect,
105	    };
106	  });
107	
108	  const correct = breakdown.filter((item: any) => item.isCorrect).length;
109	  const score = Number(((correct / totalQ) * 100).toFixed(2));
110	  const passed = score >= 50;
111	
112	  const result = await prisma.quizResult.upsert({
113	    where: { studentId_quizId: { studentId: session.id, quizId } },
114	    update: { score, totalQ, completedAt: new Date(), allowRetake: false, startedAt: dbStartedAt },
115	    create: { studentId: session.id, quizId, score, totalQ, startedAt: dbStartedAt },
116	  });
117	
118	  // Save per-question answers (enables "view answers" + "wrong questions exam")
119	  // Delete old answers for this result first (retake scenario)
120	  await prisma.quizAnswer.deleteMany({ where: { resultId: result.id } });
121	  if (breakdown.length > 0) {
122	    await prisma.quizAnswer.createMany({
123	      data: (breakdown as any[]).map((b) => ({
124	        studentId:      session.id,
125	        quizId,
126	        questionId:     b.questionId,
127	        resultId:       result.id,
128	        selectedAnswer: b.yourAnswer,
129	        correctAnswer:  b.correctAnswer,
130	        isCorrect:      b.isCorrect,
131	        question:       b.question,
132	        optionA:        b.optionA,
133	        optionB:        b.optionB,
134	        optionC:        b.optionC,
135	        optionD:        b.optionD,
136	      })),
137	    });
138	  }
139	
140	  // Points Logic: Award points only once per achievement milestone (Idempotent)
141	  if (session.role === "student") {
142	    const { addPoints, POINTS } = await import("@/lib/points");
143	    let pointsEarned = 0;
144	    
145	    // First try bonus: awarded only on the very first completion if passed
146	    const isFirstAttempt = !existingResult?.completedAt;
147	    if (isFirstAttempt && passed) {
148	      pointsEarned += POINTS.FIRST_TRY_BONUS;
149	    }
150	    
151	    // Perfect score bonus: awarded only if they achieve 100% and hadn't scored 100% previously
152	    const previousScore = existingResult?.completedAt ? existingResult.score : 0;
153	    if (score === 100 && previousScore < 100) {
154	      pointsEarned += POINTS.EXAM_FULL_SCORE;
155	    }
156	    
157	    if (pointsEarned > 0) {
158	      await addPoints(session.id, pointsEarned);
159	    }
160	  }
161	
162	  // Update Plan Lesson Progress
163	  if (planEnrollmentId && quiz.planLessonId) {
164	    await prisma.planLessonProgress.upsert({
165	      where: {
166	        enrollmentId_planLessonId: {
167	          enrollmentId: planEnrollmentId,
168	          planLessonId: quiz.planLessonId
169	        }
170	      },
171	      create: {
172	        enrollmentId: planEnrollmentId,
173	        planLessonId: quiz.planLessonId,
174	        quizPassed: passed,
175	        quizScore: score
176	      },
177	      update: {
178	        quizPassed: passed,
179	        quizScore: score
180	      }
181	    });
182	  }
183	
184	  return NextResponse.json({
185	    result,
186	    correct,
187	    totalQ,
188	    score,
189	    passed,
190	    breakdown,
191	    quizTitle: quiz.title,
192	    courseId: quiz.folder?.courseId ?? 'plan',
193	  });
194	}

