6	/** GET /api/homework/[id] — student fetches homework details (answers hidden) */
7	export async function GET(
8	  req: NextRequest,
9	  { params }: { params: Promise<{ id: string }> }
10	) {
11	  const session = await getSession();
12	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
13	
14	  const { id: homeworkId } = await params;
15	
16	  const homework = await prisma.homework.findUnique({
17	    where: { id: homeworkId },
18	    include: {
19	      questions: {
20	        orderBy: { order: "asc" },
21	        select: {
22	          id: true,
23	          question: true,
24	          imageUrl: true,
25	          optionA: true,
26	          optionB: true,
27	          optionC: true,
28	          optionD: true,
29	          order: true,
30	          // correctAnswer is intentionally omitted for students
31	        },
32	      },
33	    },
34	  });
35	
36	  if (!homework) return NextResponse.json({ error: "الواجب غير موجود" }, { status: 404 });
37	
38	  // Access check: ensures student is enrolled or teacher owns the course
39	  const hasAccess = await checkHomeworkAccess(session.id, session.role, homeworkId);
40	  if (!hasAccess) {
41	    return NextResponse.json({ error: "غير مصرح لك بالوصول لهذا الواجب" }, { status: 403 });
42	  }
43	
44	  // Student: only published
45	  if (session.role === "student" && !homework.isPublished)
46	    return NextResponse.json({ error: "الواجب غير منشور" }, { status: 403 });
47	
48	  // Strip sensitive fields for students
49	  const safe = {
50	    ...homework,
51	    expectedOutput: session.role === "student" ? null : homework.expectedOutput,
52	  };
53	
54	  return NextResponse.json({ homework: safe });
55	}

1	import { NextRequest, NextResponse } from "next/server";
2	import { getSession } from "@/lib/auth";
3	import { prisma } from "@/lib/prisma";
4	import { evaluateTerminalWithAI } from "@/lib/ai-service";
5	import { checkHomeworkAccess } from "@/lib/authorization";
