9	/** Normalize output: collapse whitespace, trim lines, lowercase */
10	function normalizeOutput(s: string): string {
11	  return s
12	    .split("\n")
13	    .map((l) => l.trim().replace(/\s+/g, " "))
14	    .filter(Boolean)
15	    .join("\n")
16	    .toLowerCase();
17	}
