19	/** POST /api/homework/[id]/submit */
20	export async function POST(
21	  req: NextRequest,
22	  { params }: { params: Promise<{ id: string }> }
23	) {
24	  const session = await getSession();
25	  if (!session || session.role !== "student")
26	    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
27	
28	  const { id: homeworkId } = await params;
29	
30	  const hw = await prisma.homework.findUnique({
31	    where: { id: homeworkId },
32	    include: { questions: { orderBy: { order: "asc" } } },
33	  });
34	
35	  if (!hw || !hw.isPublished)
36	    return NextResponse.json({ error: "الواجب غير موجود" }, { status: 404 });
37	
38	  // Enforce enrollment validation
39	  const hasAccess = await checkHomeworkAccess(session.id, session.role, homeworkId);
40	  if (!hasAccess) {
41	    return NextResponse.json({ error: "غير مصرح لك بالوصول لهذا الواجب" }, { status: 403 });
42	  }
43	
44	  // Prevent re-submission
45	  const existing = await prisma.homeworkSubmission.findUnique({
46	    where: { homeworkId_studentId: { homeworkId, studentId: session.id } },
47	  });
48	  if (existing)
49	    return NextResponse.json(
50	      { error: "لقد أرسلت هذا الواجب بالفعل", alreadySubmitted: true, submission: existing },
51	      { status: 409 }
52	    );
53	
54	  const body = (await req.json()) as {
55	    submittedOutput?: string; // terminal
56	    fileUrl?: string;         // upload
57	    fileName?: string;        // upload
58	    answers?: Record<string, string>; // MCQ: { questionId: "A"|"B"|"C"|"D" }
59	  };
60	
61	  let status = "pending";
62	  let score: number | null = null;
63	  let totalQ: number | null = null;
64	
65	  // ── Terminal ──────────────────────────────────────────────────────────────
66	  if (hw.type === "terminal") {
67	    if (!body.submittedOutput?.trim())
68	      return NextResponse.json({ error: "يجب إدخال الناتج" }, { status: 400 });
69	
70	    const expected = normalizeOutput(hw.expectedOutput ?? "");
71	    const submitted = normalizeOutput(body.submittedOutput);
72	
73	    if (submitted === expected) {
74	      status = "passed";
75	    } else {
76	      // AI semantic fallback
77	      try {
78	        const aiResult = await evaluateTerminalWithAI(
79	          hw.codeTemplate ?? "",
80	          body.submittedOutput,
81	          hw.expectedOutput ?? "",
82	          hw.codeLanguage ?? "python"
83	        );
84	        status = aiResult.passed ? "passed" : "failed";
85	      } catch {
86	        // AI unavailable → flag for manual review
87	        status = "review_requested";
88	      }
89	    }
90	  }
91	
92	  // ── Upload ────────────────────────────────────────────────────────────────
93	  else if (hw.type === "upload") {
94	    if (!body.fileUrl)
95	      return NextResponse.json({ error: "يجب رفع ملف أولاً" }, { status: 400 });
96	    status = "pending"; // teacher reviews manually
97	  }
98	
99	  // ── Exam (MCQ) ────────────────────────────────────────────────────────────
100	  else if (hw.type === "exam") {
101	    if (!body.answers || Object.keys(body.answers).length === 0)
102	      return NextResponse.json({ error: "يجب الإجابة على الأسئلة" }, { status: 400 });
103	
104	    const questions = hw.questions;
105	    let correct = 0;
106	    for (const q of questions) {
107	      if (body.answers[q.id] === q.correctAnswer) correct++;
108	    }
109	    totalQ = questions.length;
110	    score = totalQ > 0 ? Math.round((correct / totalQ) * 100) : 0;
111	    status = score >= 50 ? "passed" : "failed";
112	  }
113	
114	  // ── Link (no submission needed) ───────────────────────────────────────────
115	  else {
116	    return NextResponse.json({ error: "هذا الواجب لا يحتاج إرسال" }, { status: 400 });
117	  }
118	
119	  const submission = await prisma.homeworkSubmission.create({
120	    data: {
121	      homeworkId,
122	      studentId:       session.id,
123	      answers:         body.answers ? JSON.stringify(body.answers) : null,
124	      score,
125	      totalQ,
126	      submittedOutput: body.submittedOutput ?? null,
127	      fileUrl:         body.fileUrl ?? null,
128	      fileName:        body.fileName ?? null,
129	      status,
130	    },
131	  });
132	
133	  return NextResponse.json({ submission, status });
134	}
