136	/** GET /api/homework/[id]/submit — student checks their own submission (teachers/admins check query param) */
137	export async function GET(
138	  req: NextRequest,
139	  { params }: { params: Promise<{ id: string }> }
140	) {
141	  const session = await getSession();
142	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
143	
144	  const { id: homeworkId } = await params;
145	
146	  const hasAccess = await checkHomeworkAccess(session.id, session.role, homeworkId);
147	  if (!hasAccess) {
148	    return NextResponse.json({ error: "غير مصرح لك بالوصول لهذا الواجب" }, { status: 403 });
149	  }
150	
151	  const { searchParams } = new URL(req.url);
152	  const targetStudentId = (session.role === "teacher" || session.role === "admin" || session.role === "superadmin")
153	    ? (searchParams.get("studentId") ?? session.id)
154	    : session.id;
155	
156	  const submission = await prisma.homeworkSubmission.findUnique({
157	    where: { homeworkId_studentId: { homeworkId, studentId: targetStudentId } },
158	    include: { review: true },
159	  });
160	
161	  return NextResponse.json({ submission });
162	}

