10	/** POST /api/homework/[id]/upload — secure file upload for homework submissions */
11	export async function POST(
12	  req: NextRequest,
13	  { params }: { params: Promise<{ id: string }> }
14	) {
15	  const session = await getSession();
16	  if (!session || session.role !== "student")
17	    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
18	
19	  const { id: homeworkId } = await params;
20	
21	  // Enforce access control check (verify student is enrolled in the homework's course)
22	  const hasAccess = await checkHomeworkAccess(session.id, session.role, homeworkId);
23	  if (!hasAccess) {
24	    return NextResponse.json({ error: "غير مصرح لك بالوصول لهذا الواجب" }, { status: 403 });
25	  }
26	
27	  const hw = await prisma.homework.findUnique({
28	    where: { id: homeworkId },
29	    select: { id: true, type: true, isPublished: true, allowedFileTypes: true },
30	  });
31	
32	  if (!hw || !hw.isPublished || hw.type !== "upload")
33	    return NextResponse.json({ error: "الواجب غير متاح لرفع الملفات" }, { status: 404 });
34	
35	  let formData: FormData;
36	  try {
37	    formData = await req.formData();
38	  } catch {
39	    return NextResponse.json({ error: "بيانات غير صحيحة" }, { status: 400 });
40	  }
41	
42	  const file = formData.get("file") as File | null;
43	  if (!file) return NextResponse.json({ error: "لم يتم إرفاق ملف" }, { status: 400 });
44	
45	  // Validate file extension
46	  if (hw.allowedFileTypes) {
47	    const allowed = hw.allowedFileTypes.split(",").map((e) => e.trim().toLowerCase());
48	    const ext = file.name.split(".").pop()?.toLowerCase() ?? "";
49	    if (!allowed.includes(ext)) {
50	      return NextResponse.json(
51	        { error: `نوع الملف غير مسموح. الأنواع المسموحة: ${hw.allowedFileTypes}` },
52	        { status: 400 }
53	      );
54	    }
55	  }
56	
57	  // Validate file size (10 MB max)
58	  if (file.size > 10 * 1024 * 1024) {
59	    return NextResponse.json({ error: "حجم الملف يجب ألا يتجاوز 10 ميجابايت" }, { status: 400 });
60	  }
61	
62	  // Save to isolated directory (NOT inside public/ — no HTTP serving)
63	  const dir = path.join(UPLOAD_BASE, homeworkId, session.id);
64	  
65	  // Clean up existing files in the directory to prevent orphaned files
66	  try {
67	    const files = await fs.readdir(dir);
68	    for (const f of files) {
69	      await fs.unlink(path.join(dir, f));
70	    }
71	  } catch (e) {
72	    // Directory might not exist yet, ignore
73	  }
74	
75	  await fs.mkdir(dir, { recursive: true });
76	
77	  const safeFileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, "_")}`;
78	  const filePath = path.join(dir, safeFileName);
79	
80	  const buffer = Buffer.from(await file.arrayBuffer());
81	  await fs.writeFile(filePath, buffer);
82	
83	  // Return a reference path (NOT a public URL — accessed via /api/homework/[id]/file)
84	  const fileRef = `homework/${homeworkId}/${session.id}/${safeFileName}`;
85	
86	  return NextResponse.json({
87	    fileUrl: fileRef,
88	    fileName: file.name,
89	  });
90	}

