51	// POST — Send chat message
52	export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
53	  const session = await getStudentSession();
54	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
55	
56	  const { id: planId } = await params;
57	
58	  try {
59	    const enrollment = await prisma.planEnrollment.findUnique({
60	      where: { planId_studentId: { planId, studentId: session.id } },
61	      include: { plan: true }
62	    });
63	
64	    if (!enrollment) {
65	      return NextResponse.json({ error: "لم تسجل في هذه الخطة بعد" }, { status: 403 });
66	    }
67	
68	    // Check if chat is enabled for this plan
69	    if (!enrollment.plan.chatEnabled) {
70	      return NextResponse.json({ error: "ميزة المحادثة مع المساعد الذكي معطلة لهذه الخطة" }, { status: 403 });
71	    }
72	
73	    // Expiry check (Gap 45)
74	    const now = new Date();
75	    if (enrollment.expiresAt < now) {
76	      return NextResponse.json({ error: "انتهت صلاحية اشتراكك في هذه الخطة" }, { status: 403 });
77	    }
78	
79	    const body = await req.json().catch(() => ({}));
80	    const content = String(body.content || "").trim();
81	
82	    // Content limit (Gap 20)
83	    if (!content) {
84	      return NextResponse.json({ error: "محتوى الرسالة مطلوب" }, { status: 400 });
85	    }
86	    if (content.length > 4000) {
87	      return NextResponse.json({ error: "الرسالة طويلة جداً (الحد الأقصى 4000 حرف)" }, { status: 400 });
88	    }
89	
90	    // Rate Limiting & Save student message in an atomic transaction
91	    const oneHourAgo = new Date(now.getTime() - 3600000);
92	    let studentMsg;
93	    try {
94	      studentMsg = await prisma.$transaction(async (tx) => {
95	        // Acquire advisory lock to serialize chat quota checks
96	        await acquireAdvisoryLock(`chat-limit-${session.id}`, tx);
97	
98	        const messageCount = await tx.planAIChatMessage.count({
99	          where: {
100	            studentId: session.id,
101	            enrollmentId: enrollment.id,
102	            createdAt: { gte: oneHourAgo }
103	          }
104	        });
105	
106	        if (messageCount >= 20) {
107	          throw new Error("RATE_LIMIT_EXCEEDED");
108	        }
109	
110	        return await tx.planAIChatMessage.create({
111	          data: {
112	            enrollmentId: enrollment.id,
113	            studentId: session.id,
114	            role: "user",
115	            content
116	          }
117	        });
118	      });
119	    } catch (txErr: any) {
120	      if (txErr.message === "RATE_LIMIT_EXCEEDED") {
121	        return NextResponse.json({ error: "تجاوزت الحد الأقصى المسموح به (20 رسالة في الساعة)" }, { status: 429 });
122	      }
123	      throw txErr;
124	    }
125	
126	    // History windowing: get last 20 messages (Gap 33)
127	    const pastMessages = await prisma.planAIChatMessage.findMany({
128	      where: { enrollmentId: enrollment.id },
129	      orderBy: { createdAt: "desc" },
130	      take: 20
131	    });
132	    const chatHistory = [...pastMessages].reverse();
133	
134	    // Resolve AI Providers
135	    const { primary, backup } = await resolvePlanProviders();
136	    const maxTokens = await getConfigNumberClamped("ai_max_tokens", 512, 4096);
137	
138	    const systemPrompt = `You are a helpful Egyptian study assistant tutor for the educational plan: "${enrollment.plan.title}".
139	Educational Stage: ${enrollment.plan.educationalStage}
140	Answer the student's question in a clear, educational, and friendly way in Arabic, matching their educational level. Keep responses focused on the study material.`;
141	
142	    let reply = "";
143	    if (primary) {
144	      try {
145	        reply = await callChatProvider(primary, systemPrompt, chatHistory, maxTokens);
146	      } catch (err) {
147	        console.error(`Primary chat provider failed:`, err);
148	      }
149	    }
150	
151	    if (!reply && backup) {
152	      try {
153	        reply = await callChatProvider(backup, systemPrompt, chatHistory, maxTokens);
154	      } catch (err) {
155	        console.error(`Backup chat provider failed:`, err);
156	      }
157	    }
158	
159	    if (!reply) {
160	      return NextResponse.json({ error: "مساعد الذكاء الاصطناعي غير متوفر حالياً" }, { status: 503 });
161	    }
162	
163	    // Save assistant reply
164	    const assistantMsg = await prisma.planAIChatMessage.create({
165	      data: {
166	        enrollmentId: enrollment.id,
167	        studentId: session.id,
168	        role: "assistant",
169	        content: reply
170	      }
171	    });
172	
173	    return NextResponse.json({ message: assistantMsg });
174	  } catch (error) {
175	    console.error("Chat POST error:", error);
176	    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
177	  }
178	}
179	
180	async function callChatProvider(
181	  provider: ResolvedProvider,
182	  systemPrompt: string,
183	  history: Array<{ role: string; content: string }>,
184	  maxTokens: number
185	): Promise<string> {
186	  const base = provider.baseUrl.replace(/\/+$/, "");
187	
188	  // Format messages
189	  const formattedMessages = history.map(h => ({
190	    role: h.role === "assistant" ? "assistant" : "user",
191	    content: h.content
192	  }));
193	
194	  if (provider.kind === "anthropic") {
195	    const res = await fetch(base, {
196	      method: "POST",
197	      headers: {
198	        "Content-Type": "application/json",
199	        "x-api-key": provider.key,
200	        "anthropic-version": "2023-06-01"
201	      },
202	      body: JSON.stringify({
203	        model: provider.model,
204	        max_tokens: maxTokens,
205	        system: systemPrompt,
206	        messages: formattedMessages
207	      }),
208	      signal: AbortSignal.timeout(15000),
209	    });
210	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
211	    const data = await res.json() as { content?: Array<{ text?: string }> };
212	    return data.content?.[0]?.text || "";
213	  } else if (provider.kind === "gemini") {
