5	export async function GET(req: NextRequest) {
6	  const session = await getSession();
7	  if (!session || (session.role !== "superadmin" && session.role !== "teacher")) {
8	    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
9	  }
10	
11	  const { searchParams } = new URL(req.url);
12	  const status = searchParams.get("status") || undefined;
13	  const page = Math.max(1, Number(searchParams.get("page")) || 1);
14	  const limit = Math.max(1, Math.min(100, Number(searchParams.get("limit")) || 20));
15	
16	  try {
17	    const where: any = {};
18	    if (status) {
19	      where.status = status;
20	    }
21	
22	    if (session.role === "teacher") {
23	      const teacherLessons = await prisma.planLessonSource.findMany({
24	        where: { teacherId: session.id },
25	        select: { planLessonId: true }
26	      });
27	      where.planLessonId = { in: teacherLessons.map(t => t.planLessonId) };
28	    }
29	
30	    const submissions = await prisma.planProjectSubmission.findMany({
31	      where,
32	      include: {
33	        student: { select: { id: true, name: true, email: true } },
34	        enrollment: {
35	          select: {
36	            progress: {
37	              select: {
38	                planLessonId: true,
39	                chosenSourceId: true,
40	              }
41	            }
42	          }
43	        }
44	      },
45	      orderBy: { submittedAt: "desc" }
46	    });
47	
48	    const planLessonIds = submissions.map(s => s.planLessonId);
49	    const lessons = await prisma.planLesson.findMany({
50	      where: { id: { in: planLessonIds } },
51	      select: {
52	        id: true,
53	        title: true,
54	        sources: {
55	          select: {
56	            id: true,
57	            teacherId: true,
58	          }
59	        }
60	      }
61	    });
62	
63	    const lessonMap = new Map(lessons.map(l => [l.id, l]));
64	
65	    // Scoped filtering for teachers
66	    let filteredSubmissions = submissions.map(sub => {
67	      const lesson = lessonMap.get(sub.planLessonId);
68	      return {
69	        ...sub,
70	        planLesson: lesson ? {
71	          title: lesson.title,
72	          sources: lesson.sources
73	        } : null
74	      };
75	    });
76	
77	    if (session.role === "teacher") {
78	      filteredSubmissions = filteredSubmissions.filter(sub => {
79	        if (!sub.planLesson) return false;
80	        const progress = sub.enrollment.progress.find((p: any) => p.planLessonId === sub.planLessonId);
81	        const teacherSources = sub.planLesson.sources.filter((s: any) => s.teacherId === session.id);
82	        const teacherSourceIds = new Set(teacherSources.map((s: any) => s.id));
83	        
84	        if (progress?.chosenSourceId) {
85	          return teacherSourceIds.has(progress.chosenSourceId);
86	        }
87	        return teacherSources.length > 0;
88	      });
89	    }
90	
91	    // In-memory pagination
92	    const total = filteredSubmissions.length;
93	    const paginated = filteredSubmissions.slice((page - 1) * limit, page * limit);
94	
95	    return NextResponse.json({
96	      submissions: paginated,
97	      total,
98	      page,
99	      limit
100	    });
101	  } catch (error) {
102	    console.error("Failed to fetch submissions:", error);
103	    return NextResponse.json({ error: "تعذر جلب التقييمات" }, { status: 500 });
104	  }
105	}

1	export interface EvaluationResult {
2	  passed: boolean;
3	  score: number; // 0 to 100
4	  confidence: number; // 0.0 to 1.0
5	  feedback: string;
6	  pointsEarned: number;
7	}
8	
9	export class ProjectGrader {
10	  /**
11	   * Multi-layered AI & Rule-based Project Evaluator
12	   */
13	  public static evaluateSubmission(params: {
14	    submissionContent: string;
15	    fileUrl?: string;
16	    lessonTitle: string;
17	    hasPreviousPassingGrade: boolean;
18	  }): EvaluationResult {
19	    const { submissionContent, fileUrl, lessonTitle, hasPreviousPassingGrade } = params;
20	    const content = String(submissionContent || "").trim();
21	
22	    // ── Layer 1: Minimum Length Verification ──
23	    if (content.length < 50 && !fileUrl) {
24	      return {
25	        passed: false,
26	        score: 0,
27	        confidence: 1.0,
28	        feedback: "عذراً، محتوى التسليم قصير جداً. يرجى تقديم كود برمجي متكامل أو إضافة رابط مشروع فعّال.",
29	        pointsEarned: 0,
30	      };
31	    }
32	
33	    // ── Layer 2: Heuristic Junk & Placeholder Rejection ──
34	    const JUNK_PATTERNS = [
35	      /^[\s\d\W]+$/, // Only symbols or numbers
36	      /(hello|test|abc|12345|console\.log\("hi"\)){3,}/i,
37	      /(a{10,}|1{10,}|0{10,})/,
38	    ];
39	
40	    if (JUNK_PATTERNS.some((pattern) => pattern.test(content))) {
41	      return {
42	        passed: false,
43	        score: 10,
44	        confidence: 0.95,
45	        feedback: "تم رفض التسليم: المحتوى المقدم يحتوي على نصوص وهمية أو رموز غير برمجية.",
46	        pointsEarned: 0,
47	      };
48	    }
49	
50	    // ── Layer 3: Structural Code Pattern Detection ──
51	    const CODE_STRUCTURE_KEYWORDS = [
52	      "function", "const", "let", "var", "if", "else", "for", "while",
53	      "return", "import", "class", "def", "public", "void", "print", "console.log"
54	    ];
55	
56	    const matchedStructures = CODE_STRUCTURE_KEYWORDS.filter((kw) =>
57	      new RegExp(`\\b${kw}\\b`, "i").test(content)
58	    ).length;
59	
60	    const isStructuredCode = matchedStructures >= 2 || Boolean(fileUrl);
61	
62	    if (!isStructuredCode) {
63	      return {
64	        passed: false,
65	        score: 30,
66	        confidence: 0.85,
67	        feedback: "الكود المقدم يفتقر إلى البنية البرمجية الأساسية (دوال، متغيرات، أوتعليمات شرطية).",
68	        pointsEarned: 0,
69	      };
70	    }
71	
72	    // ── Layer 4: Passing Evaluation & Idempotent XP Calculation ──
73	    const computedScore = Math.min(100, 70 + matchedStructures * 5);
74	    const passed = computedScore >= 60;
75	
76	    // Idempotency: Award +150 XP ONLY if the student hasn't previously passed this project
77	    const pointsEarned = (passed && !hasPreviousPassingGrade) ? 150 : 0;
78	
79	    return {
80	      passed,
81	      score: computedScore,
82	      confidence: 0.9,
83	      feedback: passed
84	        ? `ممتاز! تم اجتياز مشروع (${lessonTitle}) بنجاح. الكود منظم ويحتوي على البنية البرمجية المطلوبة.`
85	        : "يتطلب المشروع تحسيناً إضافياً لتحقيق معايير الجودة المطلوبة.",
86	      pointsEarned,
87	    };
88	  }
89	}

