4	export type ReferralStatus = "PENDING" | "QUALIFIED" | "REWARDED" | "INVALID";
5	
6	export class ReferralService {
7	  /**
8	   * Registers a new PENDING referral link when student B signs up using Student A's referral code.
9	   * Does NOT award any points on raw signup to prevent bot farming.
10	   */
11	  public static async registerPendingReferral(
12	    inviterId: string,
13	    invitedId: string
14	  ): Promise<boolean> {
15	    if (inviterId === invitedId) {
16	      console.warn(`[ReferralService] Rejected self-referral for user ${inviterId}`);
17	      return false;
18	    }
19	
20	    try {
21	      await prisma.referral.create({
22	        data: {
23	          inviterId,
24	          invitedId,
25	          status: "PENDING",
26	        },
27	      });
28	      return true;
29	    } catch (err) {
30	      // Handles UNIQUE(invitedId) constraint if user was already referred
31	      console.warn(`[ReferralService] User ${invitedId} already has a referral record.`);
32	      return false;
33	    }
34	  }
35	
36	  /**
37	   * Qualifies and awards referral rewards (POINTS.REFERRAL to inviter & invited student)
38	   * upon a valid paid course purchase or access code redemption.
39	   * 
40	   * Atomically transitions status PENDING -> QUALIFIED -> REWARDED inside a transaction.
41	   */
42	  public static async qualifyAndRewardReferral(
43	    invitedStudentId: string,
44	    qualifyingPurchaseId: string
45	  ): Promise<{ rewarded: boolean; pointsAwarded: number }> {
46	    return await prisma.$transaction(async (tx) => {
47	      const referral = await tx.referral.findUnique({
48	        where: { invitedId: invitedStudentId },
49	      });
50	
51	      if (!referral) {
52	        return { rewarded: false, pointsAwarded: 0 };
53	      }
54	
55	      // Must be in PENDING status and not previously rewarded
56	      if (referral.status !== "PENDING") {
57	        return { rewarded: false, pointsAwarded: 0 };
58	      }
59	
60	      // Transition to REWARDED state atomically
61	      await tx.referral.update({
62	        where: { id: referral.id },
63	        data: {
64	          status: "REWARDED",
65	          qualifyingPurchaseId,
66	          rewardedAt: new Date(),
67	        },
68	      });
69	
70	      // Award POINTS.REFERRAL (+50 XP) to inviter & invited student
71	      const rewardPoints = POINTS.REFERRAL ?? 50;
72	      await tx.user.update({
73	        where: { id: referral.inviterId },
74	        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
75	      });
76	
77	      await tx.user.update({
78	        where: { id: referral.invitedId },
79	        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
80	      });
81	
82	      // Audit Log
83	      await tx.auditLog.create({
84	        data: {
85	          userId: referral.invitedId,
86	          action: "REFERRAL_REWARDED",
87	          ip: "127.0.0.1",
88	          metadata: JSON.stringify({
89	            inviterId: referral.inviterId,
90	            invitedId: referral.invitedId,
91	            qualifyingPurchaseId,
92	            rewardPoints,
93	          }),
94	        },
95	      }).catch(() => {});
96	
97	      console.log(`[ReferralService] Successfully rewarded ${rewardPoints} XP to inviter ${referral.inviterId} and invited ${referral.invitedId}`);
98	
99	      return { rewarded: true, pointsAwarded: rewardPoints };
100	    });
101	  }
102	
103	  /**
104	   * Retrieves summary telemetry of referrals for admin security dashboard.
105	   */
106	  public static async getReferralTelemetry(): Promise<{
107	    pending: number;
108	    qualified: number;
109	    rewarded: number;
110	    invalid: number;
111	    total: number;
112	  }> {
113	    const [pending, qualified, rewarded, invalid, total] = await Promise.all([
114	      prisma.referral.count({ where: { status: "PENDING" } }),
115	      prisma.referral.count({ where: { status: "QUALIFIED" } }),
116	      prisma.referral.count({ where: { status: "REWARDED" } }),
117	      prisma.referral.count({ where: { status: "INVALID" } }),
118	      prisma.referral.count(),
119	    ]);
120	
121	    return { pending, qualified, rewarded, invalid, total };
122	  }
123	}

