1	type PlanPricing = {
2	  price: number;
3	  discountPrice: number | null;
4	  discountExpiresAt: Date | null;
5	};
6	
7	/**
8	 * Calculates the effective price of a plan.
9	 * Reverts to the base price if the discount has expired.
10	 */
11	export function getEffectivePlanPrice(plan: PlanPricing): number {
12	  if (
13	    plan.discountPrice !== null &&
14	    plan.discountExpiresAt !== null &&
15	    plan.discountExpiresAt.getTime() > Date.now()
16	  ) {
17	    return plan.discountPrice;
18	  }
19	  return plan.price;
20	}
21	
22	/**
23	 * Checks if a plan enrollment is still active (not expired).
24	 */
25	export function isPlanEnrollmentValid(enrollment: { expiresAt: Date }): boolean {
26	  return enrollment.expiresAt.getTime() > Date.now();
27	}
28	
29	type LessonDef = {
30	  id: string;
31	  order: number;
32	  gatesNextLesson: boolean;
33	  requiresQuiz: boolean;
34	  requiresHomework: boolean;
35	  hasProject: boolean;
36	};
37	
38	type ProgressDef = {
39	  planLessonId: string;
40	  watched: boolean;
41	  quizPassed: boolean;
42	  homeworkPassed: boolean;
43	  projectPassed: boolean | null;
44	};
45	
46	/**
47	 * Determines if a student can access a specific lesson in a plan based on their progress.
48	 * Validates that all prior lessons with `gatesNextLesson=true` have been fully completed.
49	 */
50	export function canAccessPlanLesson(
51	  enrollment: { expiresAt: Date },
52	  lessonOrder: number,
53	  allLessons: LessonDef[],
54	  allProgress: ProgressDef[]
55	): boolean {
56	  if (!isPlanEnrollmentValid(enrollment)) {
57	    // If enrollment is expired, they can't access any new content
58	    // Note: The UI may still show past progress as read-only.
59	    return false;
60	  }
61	
62	  // Find all lessons before this one that act as gates
63	  const gatingLessons = allLessons
64	    .filter((l) => l.order < lessonOrder && l.gatesNextLesson)
65	    .sort((a, b) => a.order - b.order);
66	
67	  // If any gating lesson is not fully completed, access to the current lesson is denied
68	  for (const gate of gatingLessons) {
69	    const p = allProgress.find((prog) => prog.planLessonId === gate.id);
70	    if (!p) return false; // No progress record at all -> not completed
71	    
72	    if (!p.watched) return false;
73	    if (gate.requiresQuiz && !p.quizPassed) return false;
74	    if (gate.requiresHomework && !p.homeworkPassed) return false;
75	    if (gate.hasProject && !p.projectPassed) return false;
76	  }
77	
78	  return true;
79	}

