1	import { prisma } from "@/lib/prisma";
2	import { resolvePlanProviders, type ResolvedProvider } from "@/lib/ai-provider";
3	import { notifyProjectGraded } from "@/lib/notifications";
4	import { getConfigNumberClamped } from "@/lib/config";
5	
6	interface GradingResult {
7	  passed: boolean;
8	  grade: number;
9	  feedback: string;
10	}
11	
12	const SYSTEM_PROMPT = `You are a strict programming tutor. Evaluate the student's project submission based on the lesson title.
13	Provide a grade from 0 to 100, passed (true if grade >= 50, false otherwise), and constructive feedback in Arabic.
14	You must return only a valid JSON object matching this structure:
15	{
16	  "passed": true,
17	  "grade": 85,
18	  "feedback": "ملاحظاتك هنا باللغة العربية"
19	}`;
20	
21	async function callGradingProvider(
22	  provider: ResolvedProvider,
23	  lessonTitle: string,
24	  submissionContent: string,
25	  maxTokens: number
26	): Promise<GradingResult> {
27	  const base = provider.baseUrl.replace(/\/+$/, "");
28	  const prompt = `Lesson Title: ${lessonTitle}\nStudent Submission:\n${submissionContent}\n\nEvaluate the submission and return the JSON.`;
29	  let responseText = "";
30	
31	  if (provider.kind === "anthropic") {
32	    const res = await fetch(base, {
33	      method: "POST",
34	      headers: {
35	        "Content-Type": "application/json",
36	        "x-api-key": provider.key,
37	        "anthropic-version": "2023-06-01",
38	      },
39	      body: JSON.stringify({
40	        model: provider.model,
41	        max_tokens: maxTokens,
42	        system: SYSTEM_PROMPT,
43	        messages: [{ role: "user", content: prompt }],
44	      }),
45	      signal: AbortSignal.timeout(20000),
46	    });
47	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
48	    const data = (await res.json()) as { content?: Array<{ text?: string }> };
49	    responseText = data.content?.[0]?.text || "";
50	  } else if (provider.kind === "gemini") {
51	    const res = await fetch(`${base}/${provider.model}:generateContent?key=${provider.key}`, {
52	      method: "POST",
53	      headers: { "Content-Type": "application/json" },
54	      body: JSON.stringify({
55	        contents: [{ parts: [{ text: `${SYSTEM_PROMPT}\n\n${prompt}` }] }],
56	        generationConfig: { maxOutputTokens: maxTokens },
57	      }),
58	      signal: AbortSignal.timeout(20000),
59	    });
60	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
61	    const data = (await res.json()) as {
62	      candidates?: Array<{ content?: { parts?: Array<{ text?: string }> } }>;
63	    };
64	    responseText = data.candidates?.[0]?.content?.parts?.[0]?.text || "";
65	  } else {
66	    // OpenAI-compatible
67	    const res = await fetch(`${base}/chat/completions`, {
68	      method: "POST",
69	      headers: { "Content-Type": "application/json", Authorization: `Bearer ${provider.key}` },
70	      body: JSON.stringify({
71	        model: provider.model,
72	        max_tokens: maxTokens,
73	        messages: [
74	          { role: "system", content: SYSTEM_PROMPT },
75	          { role: "user", content: prompt },
76	        ],
77	      }),
78	      signal: AbortSignal.timeout(20000),
79	    });
80	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
81	    const data = (await res.json()) as { choices?: Array<{ message?: { content?: string } }> };
82	    responseText = data.choices?.[0]?.message?.content || "";
83	  }
84	
85	  // Parse JSON output
86	  const fenced = responseText.match(/```(?:json)?\s*([\s\S]*?)```/i);
87	  const candidate = (fenced ? fenced[1] : responseText).trim();
88	  const start = candidate.indexOf("{");
89	  const end = candidate.lastIndexOf("}");
90	  if (start === -1 || end === -1) throw new Error("No JSON object found in response");
91	  const parsed = JSON.parse(candidate.slice(start, end + 1)) as GradingResult;
92	
93	  if (typeof parsed.passed !== "boolean" || typeof parsed.grade !== "number" || typeof parsed.feedback !== "string") {
94	    throw new Error("Invalid grading schema from LLM");
95	  }
96	
97	  return parsed;
98	}
