100	export async function evaluateProjectWithAI(submissionId: string): Promise<void> {
101	  // 1. Atomic status transition: pending -> processing
102	  const now = new Date();
103	  const affected = await prisma.planProjectSubmission.updateMany({
104	    where: { id: submissionId, status: "pending" },
105	    data: { status: "processing" },
106	  });
107	
108	  if (affected.count === 0) {
109	    // Already claimed or graded
110	    return;
111	  }
112	
113	  const submission = await prisma.planProjectSubmission.findUnique({
114	    where: { id: submissionId },
115	  });
116	
117	  if (!submission) return;
118	
119	  // Retrieve lesson title
120	  const lesson = await prisma.planLesson.findUnique({
121	    where: { id: submission.planLessonId },
122	    select: { title: true },
123	  });
124	  const lessonTitle = lesson?.title ?? "مشروع عملي";
125	
126	  try {
127	    const { primary, backup } = await resolvePlanProviders();
128	    const maxTokens = await getConfigNumberClamped("ai_max_tokens", 512, 8192);
129	
130	    let result: GradingResult | null = null;
131	    if (primary) {
132	      try {
133	        result = await callGradingProvider(primary, lessonTitle, submission.content, maxTokens);
134	      } catch (err) {
135	        console.error(`Primary AI grading failed:`, err);
136	      }
137	    }
138	
139	    if (!result && backup) {
140	      try {
141	        result = await callGradingProvider(backup, lessonTitle, submission.content, maxTokens);
142	      } catch (err) {
143	        console.error(`Backup AI grading failed:`, err);
144	      }
145	    }
146	
147	    if (!result) {
148	      throw new Error("All AI grading providers failed");
149	    }
150	
151	    // Success: Transactional write to submission + progress + notification
152	    await prisma.$transaction(async (tx) => {
153	      await tx.planProjectSubmission.update({
154	        where: { id: submissionId },
155	        data: {
156	          status: "graded",
157	          grade: result!.grade,
158	          feedback: result!.feedback,
159	          gradedAt: now,
160	        },
161	      });
162	
163	      await tx.planLessonProgress.upsert({
164	        where: {
165	          enrollmentId_planLessonId: {
166	            enrollmentId: submission.enrollmentId,
167	            planLessonId: submission.planLessonId,
168	          },
169	        },
170	        create: {
171	          enrollmentId: submission.enrollmentId,
172	          planLessonId: submission.planLessonId,
173	          projectPassed: result!.passed,
174	          projectGrade: result!.grade,
175	        },
176	        update: {
177	          projectPassed: result!.passed,
178	          projectGrade: result!.grade,
179	        },
180	      });
181	    });
182	
183	    // Notify student
184	    await notifyProjectGraded(submission.studentId, lessonTitle, result.grade);
185	  } catch (error) {
186	    console.error(`Grading queue error for submission ${submissionId}:`, error);
187	    
188	    // Failure handling: increment retryCount and revert status to pending or set to failed
189	    const updatedSubmission = await prisma.planProjectSubmission.findUnique({
190	      where: { id: submissionId },
191	      select: { retryCount: true },
192	    });
193	
194	    const currentRetry = (updatedSubmission?.retryCount ?? 0) + 1;
195	    const finalStatus = currentRetry >= 3 ? "failed" : "pending";
196	
197	    await prisma.planProjectSubmission.update({
198	      where: { id: submissionId },
199	      data: {
200	        status: finalStatus,
201	        retryCount: currentRetry,
202	      },
203	    });
204	  }
205	}

1	import crypto from "crypto";
2	
3	// Generic type to accept a Prisma transaction object without importing the full Client
4	type PrismaTransactionClient = {
5	  $executeRawUnsafe: (query: string, ...values: any[]) => Promise<any>;
6	};
7	
8	/**
9	 * Acquires a transaction-scoped advisory lock in PostgreSQL.
10	 * If running in SQLite (development), this safely acts as a no-op since
11	 * SQLite already serializes writes natively.
12	 * 
13	 * The lock is automatically released when the transaction commits or rolls back.
14	 * 
15	 * @param lockName A unique string key for the lock
16	 * @param tx The active Prisma transaction client
17	 */
18	export async function acquireAdvisoryLock(
19	  lockName: string,
20	  tx: PrismaTransactionClient
21	): Promise<void> {
22	  const isPg = (process.env.DATABASE_URL ?? "").startsWith("postgres");
23	  if (!isPg) {
24	    // SQLite doesn't need or support this
25	    return;
26	  }
27	
28	  // Generate a 32-bit integer hash for the lockName to use with pg_advisory_xact_lock
29	  const hash = crypto.createHash("md5").update(lockName).digest();
30	  const lockId = hash.readInt32LE(0); 
31	
32	  try {
33	    await tx.$executeRawUnsafe(`SELECT pg_advisory_xact_lock(${lockId})`);
34	  } catch (error) {
35	    console.error(`Failed to acquire advisory lock for '${lockName}':`, error);
36	    throw error;
37	  }
38	}

